INSERT INTO routes (id, kind, name, region, status, difficulty, distance_km, gain_m, loss_m, date_start, date_end, from_point, to_point, season, forecast_link, bus_link, bdz_link, avtogari_link, route_line, verification_level, transport, huts, risk, days, accommodation, taxis, windy_embed, notes_default) VALUES ('S05', 'detailed', 'вр. Мургаш', 'Стара планина', 'Идея', 'Средна', 12, 800, 800, '', '', '', '', 'Април – Ноември', 'https://www.google.com/search?q=weather+Buhovo+Svoge', 'https://www.busexpress.bg/', 'https://razpisanie.bdz.bg/', 'https://avtogari.info/', 'Бухово → х. Мургаш → Своге, с възможни алтернативи по билни или по-ниски горски пътеки според сезона и времето.', 'СРЕДНО — базовите данни са дадени от теб; не мога да потвърдя независими контакти, GPS и капацитет на хижата без допълнително търсене.', '{"summary":"Възможен е с кола или комбинирано с градски/регионален транспорт до Бухово и от Своге.","car":{"available":true,"text":"Достъпът до Бухово е удобен с кола, а Своге е лесен изходен пункт; комбинацията е практична за еднопосочен преход.","parkingNote":"Провери места за паркиране в Бухово и около гара Своге."},"public":{"steps":[{"from":"София","to":"Бухово","mode":"Градски/регионален транспорт","time":"зависи от връзките","note":"Подходящ старт за ранно тръгване."},{"from":"Своге","to":"София","mode":"Влак","time":"около 1–1.5 ч","note":"Удобен финал."}]}}'::jsonb, '[{"name":"х. Мургаш","elevation":null,"beds":null,"officialPhone":"0888 38 05 30","altPhone":null,"email":null,"gps":null,"verified":true,"conflict":"Имам само подадения от теб телефон; не мога да го потвърдя с втори източник в тази сесия."}]'::jsonb, '{"level":"СРЕДЕН","color":"amber","points":["Може да има открито билно време и силен вятър около Мургаш.","Логистиката е сравнително добра, но хижата не е верифицирана допълнително.","Базовата денивелация е умерена, но теренът може да е изморителен."],"conclusion":"Баланс между логистика и натоварване; подходящ за средно опитни туристи при стабилно време."}'::jsonb, '[{"date":"2026-07-16","label":"Бухово → х. Мургаш → Своге","type":"Преход","distance":"12 км","gain":"+800 м","time":"4.5–6.5 ч","stay":"Своге","difficulty":"Средна"}]'::jsonb, '[{"name":"Къщи за гости в Бухово","location":"Бухово","rating":null,"price":null,"note":"Удобно за ранен старт."},{"name":"Къщи за гости в Своге","location":"Своге","rating":null,"price":null,"note":"Подходящо за финал и връщане към София."}]'::jsonb, '[{"name":"Локални таксита от Своге и района на Бухово","phone":null,"note":"Полезни при разминаване с разписанията."}]'::jsonb, 'https://embed.windy.com/embed.html', ''),
('P06', 'detailed', 'Южен Пирин', 'Пирин', 'Идея', 'Лесна', 16, 550, 550, '', '', '', '', 'Май – Октомври', '', '', '', '', 'Гоце Делчев → х. Попови ливади → с. Делчево', 'СРЕДНО — базовите данни са ясни, но без проверка на детайлите по хижата и точния транспорт.', '{"summary":"Най-удобно е с лична кола или местно такси до началото/края; обществен транспорт е ограничен.","car":{"available":true,"text":"Достъпът до Гоце Делчев и Делчево е по асфалт; последният подход към х. Попови ливади обикновено е проходим, но трябва да се провери текущото състояние на пътя.","parkingNote":"Паркиране при хижата или в подходящи уширения; провери на място за свободни места и ограничения."},"public":{"steps":[{"from":"София","to":"Гоце Делчев","mode":"Автобус","time":"около 3.5–5 ч","note":"След това местен транспорт или такси към изходната точка."}]}}'::jsonb, '[{"name":"х. Попови ливади","elevation":null,"beds":null,"officialPhone":"0896722557","altPhone":null,"email":null,"gps":null,"verified":true,"conflict":"Наличен е само един базов телефон; не е потвърден с втори независим източник."}]'::jsonb, '{"level":"НИСЪК","color":"emerald","points":["Маршрутът е къс и сравнително ненатоварващ.","Основният риск е в логистиката и евентуална лятна жега.","Без потвърдено техническо преминаване по базовото описание."],"conclusion":"Подходящ за по-лек уикенд и за комбиниране с транспорт без кола."}'::jsonb, '[{"date":null,"label":"Гоце Делчев → х. Попови ливади → с. Делчево","type":"Преход","distance":"16 км","gain":"+550м","time":"4–6ч","stay":"х. Попови ливади или Делчево","difficulty":"Лесна"}]'::jsonb, '[{"name":"Къщи за гости в Делчево","location":"с. Делчево","rating":null,"price":null,"note":"Подходящи за финал на прехода."}]'::jsonb, '[{"name":"Местни таксита Гоце Делчев","phone":null,"note":"Подходящи за трансфер до х. Попови ливади или Делчево."}]'::jsonb, '', ''),
('P07', 'detailed', 'вр. Вихрен', 'Пирин', 'Идея', 'Висока', 7, 964, 964, '', '', '', '', 'Юни – Октомври', '', '', '', '', 'Банско → х. Бъндерица → вр. Вихрен → х. Вихрен', 'СРЕДНО/ДОБРО — базовите параметри са стабилни, но маршрутът по билото и подходите изискват сезонна проверка.', '{"summary":"Най-лесно е с лична кола до Банско и след това с планинско такси или собствен трансфер до района на хижите.","car":{"available":true,"text":"Банско е лесно достъпен с кола; до района на х. Бъндерица и х. Вихрен пътят е планински и сезонно натоварен.","parkingNote":"Паркингът около х. Вихрен е ограничен и се пълни рано; при натоварени дни паркирането може да е на по-долен участък."},"public":{"steps":[{"from":"София","to":"Банско","mode":"Автобус или влак + автобус","time":"около 3.5–5 ч","note":"От Банско се ползва местен транспорт или такси до началото на пътеката."}]}}'::jsonb, '[{"name":"х. Бъндерица","elevation":null,"beds":null,"officialPhone":"0898 868 999","altPhone":null,"email":null,"gps":null,"verified":true,"conflict":"Няма надеждно потвърдени контактни данни в наличните базови входни данни."},{"name":"х. Вихрен","elevation":null,"beds":null,"officialPhone":"0889 890 442","altPhone":null,"email":null,"gps":null,"verified":true,"conflict":"Телефонът е даден в базовите данни, но не е потвърден с втори независим източник тук."}]'::jsonb, '{"level":"ВИСОК","color":"rose","points":["Връх Вихрен е висок и изложен маршрут.","Възможни са бързи промени във времето, мъгла, силен вятър и остатъчен сняг.","Класическият подход от х. Бъндерица е технически по-взискателен от долинни преходи."],"conclusion":"Силен планински ден, подходящ само при стабилна прогноза и добра подготовка."}'::jsonb, '[{"date":null,"label":"Банско → х. Бъндерица → вр. Вихрен → х. Вихрен","type":"Преход","distance":"13 км","gain":"+964м","time":"6–8ч","stay":"х. Вихрен","difficulty":"Висока"}]'::jsonb, '[{"name":"Хотели и къщи за гости в Банско","location":"Банско","rating":null,"price":null,"note":"Най-логично за нощувка преди ранен старт."}]'::jsonb, '[{"name":"Местни таксита Банско","phone":null,"note":"Удобни за трансфер до х. Вихрен и района на х. Бъндерица."}]'::jsonb, '', '')
